#include "mspa/psychology/learning.hpp"
#include <algorithm>
namespace mspa {namespace{std::vector<std::string>canon(std::vector<std::string>x){std::sort(x.begin(),x.end());x.erase(std::unique(x.begin(),x.end()),x.end());return x;}bool same(const std::vector<std::string>&a,const std::vector<std::string>&b){return canon(a)==canon(b);}}
void LearningSystem::report(AgentPsychState&a,ActionTypeId act,bool ok)const{LearningReport r{};r.action=act;r.success=ok;r.outcome_tags={ok?"success":"failure"};r.now=a.last_processed_time;(void)report(a,r);}
Result<void>LearningSystem::report(AgentPsychState&a,const LearningReport&r,std::size_t max)const{if(!r.action.valid())return make_error(ErrorCode::InvalidArgument,"invalid learned action");auto tags=canon(r.context_tags);std::vector<std::string>out=r.outcome_tags;if(out.empty())out.push_back(r.success?"success":"failure");for(const auto&o:out){auto it=std::find_if(a.learned_expectations.begin(),a.learned_expectations.end(),[&](const auto&e){return e.action==r.action&&e.outcome_tag==o&&same(e.context_tags,tags);});if(it==a.learned_expectations.end()){if(a.learned_expectations.size()>=max)return make_error(ErrorCode::QuotaExceeded,"learning pattern quota exceeded");LearnedExpectation e{};e.action=r.action;e.context_tags=tags;e.outcome_tag=o;e.attempts=1;e.successes=(o=="success"?static_cast<std::uint32_t>(r.success):1u);e.confidence=(o=="success"?(r.success?1.0f:0.0f):1.0f);e.last_activation=r.now;a.learned_expectations.push_back(std::move(e));}else{++it->attempts;const bool occurred=(o=="success")?r.success:true;if(occurred)++it->successes;it->confidence=(static_cast<float>(it->successes)+1.0f)/(static_cast<float>(it->attempts)+2.0f);it->last_activation=r.now;}}return {};}
float LearningSystem::expected_success(const AgentPsychState&a,ActionTypeId act)const noexcept{return expected_success(a,act,{});}float LearningSystem::expected_success(const AgentPsychState&a,ActionTypeId act,const std::vector<std::string>&ctx)const noexcept{return expected_outcome(a,act,ctx,"success");}float LearningSystem::expected_outcome(const AgentPsychState&a,ActionTypeId act,const std::vector<std::string>&ctx,const std::string&o)const noexcept{const auto tags=canon(ctx);float sum=0,weight=0;for(const auto&e:a.learned_expectations){if(e.action!=act||e.outcome_tag!=o)continue;float w=same(e.context_tags,tags)?2.0f:(e.context_tags.empty()?0.75f:0.0f);if(w>0){sum+=w*e.confidence;weight+=w;}}return weight>0?sum/weight:0.5f;}}
